import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
// Font Loader Hook
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};



export type ChecklistAnimationProps = Record<string, any>;

const ChecklistAnimation: React.FC<ChecklistAnimationProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
  items = ["No Lease", "No Furnishing Cost", "No Upfront Capital"],
  textColor = "#ffffff",
  accentColor = "#4ade80",
  fontSize = 70,
  gapSize = 40,
  barWidth = 8,
}) => {
  // Load fonts - Updated to Inter for a bold sans-serif look
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safe color parsing
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Constants
  const staggerFrames = 15; // Frames between each item pop
  const springConfig = {
    damping: 12,
    stiffness: 100,
    mass: 0.8,
  };

  // Calculate layout
  const totalItems = items.length;
  // Dynamic top padding to center the list vertically
  const itemHeight = fontSize * 1.2; // Approximate height per item line
  const totalListHeight = (totalItems * itemHeight) + ((totalItems - 1) * gapSize);
  const startY = (height - totalListHeight) / 2;
  
  // Progress Bar Animation
  // The bar grows from the top of the first item to the bottom of the last *active* item
  // We want the bar to follow the items popping in.
  const totalSequenceFrames = (totalItems * staggerFrames) + 20;
  
  // Bar height interpolation
  // We map the frame progress to the percentage of height (0 to 100%)
  // It should finish growing when the last item pops in
  const barProgress = interpolate(
    frame,
    [0, totalSequenceFrames],
    [0, 1],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          top: startY,
          left: width * 0.15, // Offset from left
          height: totalListHeight,
          display: "flex",
          flexDirection: "row",
        }}
      >
        {/* Progress Bar Container */}
        <div
          style={{
            width: barWidth,
            height: "100%",
            backgroundColor: `${accentColor}33`, // Dim version for track
            borderRadius: barWidth / 2,
            marginRight: gapSize,
            position: "relative",
          }}
        >
          {/* Animated Fill Bar */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: "100%",
              height: `${barProgress * 100}%`,
              backgroundColor: accentColor,
              borderRadius: barWidth / 2,
              boxShadow: `0 0 15px ${accentColor}`,
            }}
          />
        </div>

        {/* List Items */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "space-between",
            height: "100%",
          }}
        >
          {items.map((text, index) => {
            // Per-item delay
            const delay = index * staggerFrames;
            
            // Spring animation for pop-in
            const spr = spring({
              frame: frame - delay,
              fps,
              config: springConfig,
            });

            // Scale and opacity based on spring
            const scale = interpolate(spr, [0, 1], [0, 1]);
            const opacity = interpolate(spr, [0, 0.5], [0, 1], { extrapolateRight: "clamp" });
            
            // Slide in slightly from left
            const translateX = interpolate(spr, [0, 1], [-50, 0]);

            return (
              <div
                key={index}
                style={{
                  height: itemHeight,
                  display: "flex",
                  alignItems: "center",
                  fontSize: fontSize,
                  fontFamily: "Inter, sans-serif", // Updated font family
                  fontWeight: 800, // Bold weight
                  color: textColor,
                  transform: `translateX(${translateX}px) scale(${scale})`,
                  opacity,
                  transformOrigin: "center left",
                  whiteSpace: "nowrap",
                  textShadow: "2px 2px 4px rgba(0,0,0,0.5)",
                }}
              >
                {/* Custom Checkmark Bullet */}
                <span
                  style={{
                    color: accentColor,
                    marginRight: 20,
                    fontSize: fontSize * 1.2,
                    display: "inline-block",
                    transform: `scale(${scale})`, // Extra pop for the check
                  }}
                >
                  ✓
                </span>
                {text}
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChecklistAnimation;